const compare=(title,scene,states,prompt,choices,answers,results,why)=>({type:'compare',title,scene,states,prompt,choices,answers,results,why});
export const exerciseData=[{id:'rest',label:'Rest',pulse:72,breaths:12,volume:.5},{id:'work',label:'Exercise',pulse:144,breaths:24,volume:1},{id:'recover',label:'Recovery',pulse:96,breaths:18,volume:.7}];
export function perMinute(count,seconds){return count!==''&&seconds!==''&&Number.isFinite(Number(count))&&Number.isFinite(Number(seconds))&&Number(count)>=0&&Number(seconds)>0?Number(count)*60/Number(seconds):null;}
export function extraOxygen(rate,baseline,minutes){return [rate,baseline,minutes].every(x=>x!==''&&Number.isFinite(Number(x)))&&Number(rate)>=Number(baseline)&&Number(baseline)>=0&&Number(minutes)>0?(Number(rate)-Number(baseline))*Number(minutes):null;}
export const recoveryData=[{rate:3,baseline:1,minutes:1},{rate:2,baseline:1,minutes:1},{rate:1,baseline:1,minutes:1}];
export const recoveryRoute=['muscle','blood','liver','glucose'];
export const routeAdvance=(step,action)=>step>=0&&step<4&&action===recoveryRoute[step]?step+1:step;
export const lipidValid=(g,f)=>Number(g)===1&&Number(f)===3;
